-- Separate existing booking/accounting access; swimming is always explicitly assigned.
UPDATE staff SET permissions=json_insert(permissions,'$[#]','overview') WHERE EXISTS(SELECT 1 FROM json_each(permissions) WHERE value='reservations') AND NOT EXISTS(SELECT 1 FROM json_each(permissions) WHERE value='overview');
